import lockIcon from '@jetbrains/icons/lock.svg'
import ErrorMessage from '@jetbrains/ring-ui-built/components/error-message/error-message'
import Theme from '@jetbrains/ring-ui-built/components/global/theme'
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useState} from 'react'

import EntityPath from '../../../../containers/EntityPath'
import {useQueryParam} from '../../../../hooks/routes'
import {useDarkOrLightTheme} from '../../../../hooks/theme/useDarkOrLightTheme'
import {getPipelinesHref} from '../../../../routes'
import {toProjectId} from '../../../../types'
import {LINKS} from '../../../App/Header/Header.consts'
import PageTitle from '../../../common/PageTitle/PageTitle'
import Redirect from '../../../common/Redirect/Redirect'
import RouterLink from '../../../common/RouterLink/RouterLink'
import PipelineForm from '../components/PipelineForm/PipelineForm'
import RestScreenHeight from '../components/RestScreenHeight/RestScreenHeight'
import VcsLoginScreen from '../components/VcsLoginScreen/VcsLoginScreen'
import useCanCreatePipeline from '../hooks/useCanCreatePipeline'
import usePipelineDocumentTitle from '../hooks/usePipelineDocumentTitle'
import usePipelineVcsProviders from '../hooks/usePipelineVcsProviders'
import {getAccountRootProjectId} from '../PipelinesPages.consts'
import type {VcsProvider} from '../services/pipelinesApi.types'
import {VcsProviderType} from '../services/pipelinesApi.types'
import {
  isEarlyAccessLabelEnabled,
  isPipelinesEnabledInExclusiveMode,
  isProjectsAndBuildTypesEnabled,
} from '../utils/featureToggles'

import {vcsAnyGitProvider} from './CreatePipelinePage.consts'
import {getPreselectedVcsProvider} from './CreatePipelinePage.utils'
import CreatePipelineImageDark from './Pipeline-dark.svg'
import CreatePipelineImageLight from './Pipeline-light.svg'

import styles from './CreatePipelinePage.module.css'

function CreatePipelinePageContainer() {
  const canCreatePipeline = useCanCreatePipeline()

  usePipelineDocumentTitle('Create')
  const theme = useDarkOrLightTheme()
  const [isSelectedAnyProvider, setIsSelectedAnyProvider] = useState(false)
  const CreatePipelineImage =
    theme === Theme.LIGHT ? CreatePipelineImageLight : CreatePipelineImageDark
  const projectIdString = useQueryParam('projectId')
  const parentProjectId =
    projectIdString != null ? toProjectId(projectIdString) : getAccountRootProjectId()
  const {
    isLoginScreenMode,
    vcsProviders,
    authorizedProvider,
    getVcsProvidersRefetch,
    getRefetchVcsRoots,
  } = usePipelineVcsProviders(parentProjectId)
  const buttonProviderLoginClickHandler = (value?: VcsProvider) => {
    if (value?.type === VcsProviderType.ANY) {
      setIsSelectedAnyProvider(true)
    } else {
      getRefetchVcsRoots()
      getVcsProvidersRefetch()
    }
  }
  const preselectProvider = isPipelinesEnabledInExclusiveMode()
    ? (authorizedProvider ?? vcsAnyGitProvider)
    : (authorizedProvider ?? getPreselectedVcsProvider(vcsProviders, isSelectedAnyProvider))
  const isShowVcsLoginScreen = isPipelinesEnabledInExclusiveMode()
    ? isProjectsAndBuildTypesEnabled() && authorizedProvider == null && !isSelectedAnyProvider
    : isLoginScreenMode

  if (!projectIdString && !isPipelinesEnabledInExclusiveMode()) {
    return <Redirect to={LINKS.overview.sakura} replace />
  }

  return (
    <RestScreenHeight>
      {canCreatePipeline ? (
        <div className={styles.page}>
          {vcsProviders == null ? (
            <Loader />
          ) : (
            <>
              <IconButton
                className={styles.close}
                title={'Close'}
                icon={'close-20px'}
                onClick={() => history.back()}
              />
              {isShowVcsLoginScreen ? (
                <VcsLoginScreen
                  vcsProviders={vcsProviders}
                  onLogin={buttonProviderLoginClickHandler}
                />
              ) : (
                <div className={styles.container}>
                  <div className={styles.createPipeline}>
                    <PageTitle
                      className={classNames(styles.title, {
                        [styles.withProjectSelector]: isProjectsAndBuildTypesEnabled(),
                      })}
                    >
                      <span>{'Create Pipeline'}</span>
                      {isProjectsAndBuildTypesEnabled() && isEarlyAccessLabelEnabled && (
                        <Tag
                          readOnly
                          textColor={'var(--ring-success-color)'}
                          backgroundColor={'var(--ring-added-background-color)'}
                          className={styles.earlyAccessTag}
                        >
                          {'Early access'}
                        </Tag>
                      )}
                    </PageTitle>
                    {isProjectsAndBuildTypesEnabled() && (
                      <div className={styles.parentProject}>
                        <span className={styles.parentProjectLabel}>{'Parent project:'}</span>
                        <EntityPath
                          projectOrBuildTypeNode={{nodeType: 'all'}}
                          projectId={parentProjectId}
                          withLeafStatusIcon={false}
                          withCollapsing
                          withLeafIcon
                        />
                      </div>
                    )}
                    <PipelineForm
                      key={preselectProvider?.connectionId}
                      projectId={parentProjectId}
                      vcsProviders={vcsProviders}
                      authorizedProvider={preselectProvider}
                      onVcsLogin={
                        process.env.NODE_ENV !== 'test' ? getVcsProvidersRefetch : undefined
                      }
                    />
                  </div>
                  <div className={styles.imageWrapper}>
                    <img alt="Create Pipeline" src={CreatePipelineImage} width={460} height={460} />
                  </div>
                </div>
              )}
            </>
          )}
        </div>
      ) : (
        <div className={styles.errorWrapper}>
          <ErrorMessage
            icon={lockIcon}
            message="Access denied"
            description="You do not have enough permissions to create new pipeline"
          >
            <RouterLink to={getPipelinesHref()}>{'Go to the home page'}</RouterLink>
          </ErrorMessage>
        </div>
      )}
    </RestScreenHeight>
  )
}

export default CreatePipelinePageContainer
export type CreatePipelinePageComponent = typeof CreatePipelinePageContainer
