import {Fragment} from 'react'

import PageTitle from '../../../../common/PageTitle/PageTitle'
import type {VcsProvider} from '../../services/pipelinesApi.types'
import {VcsProviderType} from '../../services/pipelinesApi.types'

import VcsLoginItem from './VcsLoginItem/VcsLoginItem'
import {description, title} from './VcsLoginScreen.consts'

import styles from './VcsLoginScreen.module.css'

type Props = {
  vcsProviders: VcsProvider[]
  onLogin?: (value?: VcsProvider) => void
}
function VcsLoginScreen({vcsProviders, onLogin}: Props) {
  const mainVcsProviders = vcsProviders.filter(
    ({type}) =>
      type !== VcsProviderType.ANY &&
      type !== VcsProviderType.EXISTING_VCS_ROOT &&
      type !== VcsProviderType.CONNECT_BY_REPOSITORY_URL,
  )
  const additionalVcsProviders = vcsProviders.filter(
    ({type}) => type === VcsProviderType.ANY || type === VcsProviderType.CONNECT_BY_REPOSITORY_URL,
  )
  const hasAdditionalVcsProviders = !!additionalVcsProviders.length

  return (
    <div className={styles.container}>
      <PageTitle>{title}</PageTitle>
      <div className={styles.description}>{description}</div>
      <div className={styles.vcsList}>
        {mainVcsProviders.map((vcsProvider, index) => {
          const key = `${vcsProvider.connectionId}-${index}`

          return <VcsLoginItem key={key} vcsProvider={vcsProvider} onLogin={onLogin} />
        })}
      </div>
      {hasAdditionalVcsProviders && (
        <Fragment>
          <div className={styles.listDivider}>
            <span className={styles.listDividerText}>{'or'}</span>
          </div>
          <div className={styles.vcsList}>
            {additionalVcsProviders.map((vcsProvider, index) => {
              const key = `${vcsProvider.connectionId}-${index}`

              return <VcsLoginItem key={key} vcsProvider={vcsProvider} onLogin={onLogin} />
            })}
          </div>
        </Fragment>
      )}
    </div>
  )
}

export default VcsLoginScreen
