import {useEffect} from 'react'

import {getAccountRootProjectId} from '../PipelinesPages.consts'
import {isProjectsAndBuildTypesEnabled} from '../utils/featureToggles'

import type {usePermissionQuery} from 'src/hooks/__generated__/usePermissionQuery.graphql'
import {useRefetchableLazyLoadQuery} from 'src/hooks/relay/useRefetchableLazyLoadQuery'
import useMyId from 'src/hooks/useMyId'
import {PermissionQuery} from 'src/hooks/usePermission'
import {getProjectPermissionsLocator} from 'src/rest/permission'
import {Permission} from 'src/types'
import {subscribeOnUserEvents} from 'src/utils/subscriber'
import * as SubscriptionEvents from 'src/utils/subscriptionEvents'

export default function useCanCreatePipeline() {
  const isRootOnlyCheck = !isProjectsAndBuildTypesEnabled()

  const projectId = getAccountRootProjectId()
  const permission = Permission.EDIT_PROJECT
  const locator = isRootOnlyCheck
    ? getProjectPermissionsLocator(permission, projectId)
    : `userPermission:(permission:${permission},user:current)`
  const subscriptionKey = isRootOnlyCheck ? `${permission}:${projectId}` : `${permission}:any`

  const [{projectsRest}, refetch] = useRefetchableLazyLoadQuery<usePermissionQuery>(
    PermissionQuery,
    {locator},
  )
  const myId = useMyId()

  useEffect(
    () =>
      myId != null
        ? subscribeOnUserEvents(
            subscriptionKey,
            myId,
            [SubscriptionEvents.USER_PERMISSIONS_CHANGED],
            refetch,
          )
        : undefined,
    [myId, subscriptionKey, refetch],
  )

  return Boolean(projectsRest?.count)
}
